def selectSong():
    global openlink
    song=random.choice(songs)
    song=song.split("|")
    country.config(text="Country: "+song[0])
    year.config(text="Year: "+song[1])
    songt.config(text="Song: "+song[3])
    artist.config(text="Artist(s): "+song[2])
    lang.config(text="Language(s): "+song[4])
    root.update()
    if openlink:
        time.sleep(2)
        webbrowser.open(song[5])
def linkbutton():
    global openlink
    global olink
